// Read-Along offline helper (service worker), generated by build_web.py.
//  - keeps the app's own files cached so it opens without internet
//  - plays books stored on this device: hands the audio player just the 4 MB pieces it asks for
const CACHE = 'read-along-48e11151e9';
const FILES = [
  "./",
  "index.html",
  "manifest.webmanifest",
  "reader/reader.js",
  "reader/notes.js",
  "reader/library-ui.js",
  "reader/offline.js",
  "reader/reader.css",
  "reader/features.css",
  "reader/icon.svg",
  "reader/icon-192.png",
  "reader/icon-256.png",
  "reader/icon-512.png",
  "reader/apple-touch-icon.png",
  "reader/vendor/epub.min.js",
  "reader/vendor/jszip.min.js",
  "reader/vendor/qrcode.min.js"
];
const CHUNK = 4 * 1024 * 1024;

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(FILES)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys()
    .then((keys) => Promise.all(keys.filter((k) => k.startsWith('read-along-') && k !== CACHE).map((k) => caches.delete(k))))
    .then(() => self.clients.claim()));
});

function openDb() {
  return new Promise((res, rej) => { const r = indexedDB.open('read-along'); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); });
}
function dbGet(db, store, key) {
  return new Promise((res, rej) => {
    const q = db.transaction(store).objectStore(store).get(key);
    q.onsuccess = () => res(q.result); q.onerror = () => rej(q.error);
  });
}

async function serveAudio(req, id) {
  const db = await openDb();
  const book = await dbGet(db, 'books', id);
  if (!book || !book.audioSize) return new Response('Not on this device', { status: 404 });
  const size = book.audioSize;
  const type = book.audioType || 'audio/mp4';
  const m = /bytes=(\d*)-(\d*)/.exec(req.headers.get('Range') || '');
  if (!m || (!m[1] && !m[2])) {
    // whole file: stream it piece by piece
    let n = 0;
    const stream = new ReadableStream({
      async pull(ctl) {
        if (n * CHUNK >= size) { ctl.close(); return; }
        ctl.enqueue(new Uint8Array(await dbGet(db, 'chunks', `${id}/audio/${n}`)));
        n++;
      },
    });
    return new Response(stream, { status: 200, headers: { 'Content-Type': type, 'Content-Length': String(size), 'Accept-Ranges': 'bytes' } });
  }
  let start, end;
  if (m[1]) { start = +m[1]; end = m[2] ? Math.min(+m[2], size - 1) : size - 1; } else { start = Math.max(0, size - +m[2]); end = size - 1; }
  if (start >= size) return new Response(null, { status: 416, headers: { 'Content-Range': `bytes */${size}` } });
  end = Math.min(end, start + 2 * CHUNK - 1);                 // at most ~8 MB per answer; the player asks for more
  const out = new Uint8Array(end - start + 1);
  let pos = 0;
  for (let n = Math.floor(start / CHUNK); n <= Math.floor(end / CHUNK); n++) {
    const piece = new Uint8Array(await dbGet(db, 'chunks', `${id}/audio/${n}`));
    const from = Math.max(start, n * CHUNK) - n * CHUNK;
    const to = Math.min(end, n * CHUNK + piece.length - 1) - n * CHUNK;
    out.set(piece.subarray(from, to + 1), pos);
    pos += to - from + 1;
  }
  return new Response(out, {
    status: 206,
    headers: { 'Content-Type': type, 'Content-Length': String(out.length), 'Content-Range': `bytes ${start}-${end}/${size}`, 'Accept-Ranges': 'bytes' },
  });
}

self.addEventListener('fetch', (e) => {
  const req = e.request;
  const url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== location.origin) return;
  const i = url.pathname.indexOf('/local-audio/');
  if (i >= 0) {
    e.respondWith(serveAudio(req, decodeURIComponent(url.pathname.slice(i + '/local-audio/'.length))));
    return;
  }
  // the app's own files: from the cache (works offline); updates arrive as a new cache version
  e.respondWith(caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).catch(() =>
    (req.mode === 'navigate' ? caches.match('index.html') : Response.error()))));
});
